export function getCase(id: string): SyntheticCase | undefined {
  return SYNTHETIC_CASES.find((c) => c.id === id);
}

/**
 * Returns the prewritten result ONLY when the current form exactly matches the
 * predefined case intake. Any edit means no canned response is shown.
 */
export function fixtureResultFor(caseId: string | null, values: IntakeFormValues): AnalysisResult | null {
  if (!caseId) return null;
  const c = getCase(caseId);
  if (!c) return null;
  return snapshotKey(intakeToForm(c.intake)) === snapshotKey(values) ? c.prewrittenResult : null;
}
